<script setup>
import {computed,ref} from 'vue'
import {useData} from 'vitepress'
import catalog from '../../data/connectors.json'
const {frontmatter}=useData(),english=computed(()=>frontmatter.value.locale==='en'),locale=computed(()=>english.value?'en':'zh')
const role=ref('ALL'),state=ref('ALL'),query=ref('')
const status={AVAILABLE:['可用','Available'],PARTIALLY_VERIFIED:['部分验证','Partially verified'],EXPERIMENTAL:['实验性','Experimental'],PLANNED:['规划中','Planned']}
const names={MYSQL:'MySQL',POSTGRESQL:'PostgreSQL',ORACLE:'Oracle',GAUSS_POSTGRESQL:'openGauss / GaussDB',DM:'达梦 DM',KINGBASE:'金仓 Kingbase',GBASE_8C:'GBase 8c',GBASE_8A:'GBase 8a',GBASE_8S:'GBase 8s',OCEANBASE:'OceanBase',CLICKHOUSE:'ClickHouse',DORIS:'Apache Doris',HIVE:'Apache Hive',KAFKA:'Apache Kafka',PULSAR:'Apache Pulsar',RABBITMQ:'RabbitMQ',ROCKETMQ:'RocketMQ',NATS_JETSTREAM:'NATS JetStream',REDIS_STREAMS:'Redis Streams',ACTIVEMQ_CLASSIC:'ActiveMQ Classic',ACTIVEMQ_ARTEMIS:'ActiveMQ Artemis'}
const docs={GAUSS_POSTGRESQL:'gaussdb-index-policy',DM:'dm-v3',KINGBASE:'kingbase-v3',GBASE_8C:'gbase8c-v3',OCEANBASE:'oceanbase-v3',CLICKHOUSE:'clickhouse-v3',DORIS:'doris-v3',HIVE:'hive-v3',ACTIVEMQ_CLASSIC:'classic-v3'}
const messaging=['KAFKA','PULSAR','RABBITMQ','ROCKETMQ','NATS_JETSTREAM','REDIS_STREAMS','ACTIVEMQ_CLASSIC','ACTIVEMQ_ARTEMIS']
const descriptions={
 MYSQL_SOURCE:'读取 MySQL 已有数据和后续变更。已覆盖指定版本的全量、增量及恢复场景，部署前核对日志和权限。',MYSQL_SINK:'将数据同步到独立 MySQL 8.4 目标，支持快照、持续变更与恢复。首次使用空目标。',POSTGRESQL:'PostgreSQL 17.12 已验证全量、增量、重启和 JSON。来源端与目标端是不同能力。',GAUSS_POSTGRESQL:'已验证 openGauss 7.0.0-RC3。商业 GaussDB 和分布式形态需要分别验证。',CLICKHOUSE:'ClickHouse 25.8 单节点，使用专用物化与读取方式处理变更；集群另行验证。',DORIS:'Doris 4.1.3 通过 Stream Load 持续写入，按 Unique MoW 视图读取；集群、安全和容量需另行验证。',HIVE:'Hive 4.0.1 的实验性适配，使用 ACID ORC 历史与视图，需要关闭查询结果缓存。',OCEANBASE:'实验性 MySQL 模式适配。原生环境验证仍待完成，Oracle 模式尚未支持。',DM:'达梦 DM8 指定 UTF8 模式的实验性适配，已验证部分同步与恢复场景；其他模式另行评估。',KINGBASE:'金仓 V9 指定 PG/UTF8 模式的实验性适配，其他模式、集群与容量需独立确认。',GBASE_8C:'GBase 8c 指定 PG/UTF8 模式的实验性适配。8a、8s 属于独立产品，不能混用。'}
function description(row){if(english.value)return row.note||'Planned capability; not currently selectable.';if(row.status==='PLANNED')return '规划中的连接能力，当前请勿作为已支持的来源或目标选择。';return descriptions[row.id+'_'+row.role]||descriptions[row.id]||(messaging.includes(row.id)?'按消息确认协议投递快照和增量事件，消费者需要去重。指定单节点场景已验证，集群和安全配置请核对连接说明。':'具体版本、部署条件和操作步骤见连接说明。')}
const rows=computed(()=>catalog.filter(row=>(role.value==='ALL'||row.role===role.value)&&(state.value==='ALL'||row.status===state.value)&&`${names[row.id]} ${row.id} ${row.note}`.toLowerCase().includes(query.value.toLowerCase())))
function href(row){if(row.status==='PLANNED')return `/docs/${locale.value}/start/roadmap.html`;return `/docs/${locale.value}/reference/${docs[row.id]||(messaging.includes(row.id)?'messaging-v3':'pipeline-v3')}.html`}
</script>
<template><div class="catalog-controls"><label>{{english?'Direction':'方向'}}<select v-model="role"><option value="ALL">{{english?'All':'全部'}}</option><option value="SOURCE">{{english?'Capture source':'采集源'}}</option><option value="SINK">{{english?'Delivery target':'同步目标'}}</option></select></label><label>{{english?'State':'状态'}}<select v-model="state"><option value="ALL">{{english?'All states':'全部状态'}}</option><option v-for="(label,key) in status" :key="key" :value="key">{{label[english?1:0]}}</option></select></label><label class="grow">{{english?'Search':'查找连接器'}}<input v-model="query" type="search" placeholder="MySQL / PostgreSQL / DM…"></label></div><p class="result-summary" aria-live="polite">{{rows.length}} {{english?'matching entries · source registry snapshot':'项匹配 · 按实际连接能力列出'}}</p><div class="connector-list"><article v-for="row in rows" :key="row.id+row.role" class="connector-entry"><div class="connector-entry-top"><span class="connector-symbol">{{row.id.slice(0,2)}}</span><span class="state-chip" :class="row.status.toLowerCase()">{{status[row.status]?.[english?1:0]||row.status}}</span></div><h2>{{names[row.id]||row.id}}</h2><span class="connector-direction">{{row.role==='SOURCE'?(english?'CAPTURE SOURCE':'采集源'):(english?'DELIVERY TARGET':'同步目标')}}</span><p>{{description(row)}}</p><a :href="href(row)">{{row.status==='PLANNED'?(english?'View roadmap':'查看规划'):(english?'Read manual':'阅读手册')}} →</a></article></div><p v-if="!rows.length">{{english?'No entries. Try different filters.':'没有匹配项，请调整筛选。'}}</p></template>
